	meta = frappe.get_meta("Email Template")

	fields = [
		{
			"default": "0",
			"fieldname": "enabled",
			"fieldtype": "Check",
			"label": "Enabled",
			"insert_after": "",
		},
		{
			"fieldname": "reference_doctype",
			"fieldtype": "Link",
			"label": "Doctype",
			"options": "DocType",
